CREATE OR REPLACE FUNCTION public.resolve_import_meet(p_name text, p_start_date date, p_end_date date, p_location text, p_course text) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE v_id uuid; BEGIN IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Solo administradores'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(jsonb_build_array(lower(btrim(p_name)),p_start_date,p_course)::text,0)); SELECT id INTO v_id FROM public.meets WHERE lower(btrim(name))=lower(btrim(p_name)) AND start_date IS NOT DISTINCT FROM p_start_date AND course=p_course ORDER BY created_at,id LIMIT 1; IF v_id IS NULL THEN INSERT INTO public.meets(name,start_date,end_date,location,course) VALUES(btrim(p_name),p_start_date,p_end_date,p_location,p_course) RETURNING id INTO v_id; END IF; RETURN v_id; END; $$; REVOKE ALL ON FUNCTION public.resolve_import_meet(text,date,date,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.resolve_import_meet(text,date,date,text,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.resolve_import_event(p_meet_id uuid,p_number text,p_distance integer,p_stroke smallint,p_gender text,p_min_age integer,p_max_age integer) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE v_id uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Solo administradores'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(jsonb_build_array(p_meet_id,p_distance,p_stroke,p_gender,p_min_age,p_max_age)::text,1)); SELECT id INTO v_id FROM public.events WHERE meet_id=p_meet_id AND distance=p_distance AND stroke=p_stroke AND gender IS NOT DISTINCT FROM p_gender AND min_age IS NOT DISTINCT FROM p_min_age AND max_age IS NOT DISTINCT FROM p_max_age AND (event_number IS NOT DISTINCT FROM p_number OR event_number IS NULL OR p_number IS NULL) ORDER BY (event_number IS NOT DISTINCT FROM p_number) DESC,id LIMIT 1; IF v_id IS NULL THEN INSERT INTO public.events(meet_id,event_number,distance,stroke,gender,min_age,max_age,is_relay) VALUES(p_meet_id,p_number,p_distance,p_stroke,p_gender,p_min_age,p_max_age,p_stroke>=6) RETURNING id INTO v_id; END IF; RETURN v_id; END; $$; REVOKE ALL ON FUNCTION public.resolve_import_event(uuid,text,integer,smallint,text,integer,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.resolve_import_event(uuid,text,integer,smallint,text,integer,integer) TO authenticated,service_role;